entries[32866] = { ["name"] = "Mächtiger Erdsturmdiamant", ["text"] = "Wirken in 12.5 sek.\nTools:\nEinfacher Schleifer\nReagenzien:\nErdsturmdiamant\nMächtiger Erdsturmdiamant\n+18 Ausdauer und Betäubungsdauer um 15% verringert\nBenötigt mindestens 3 Edelsteine der Farbe Blau\n\"Passt nur in einen Sockel der Kategorie Meta.\"" }
