entries[33736] = { ["name"] = "Wasserschild", ["text"] = "Sofort\nDer Zaubernde wird von 3 Wasserkugeln umgeben, die alle 5 Sek. 50 Mana gewähren. Trifft ein Zauber, ein Nahkampf- oder Distanzangriff den Zaubernden, erhält er 214 Mana und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 10 min lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
