entries[33907] = { ["name"] = "Dornen", ["text"] = "30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem, der es schlägt, Naturschaden zufügen. Hält 10 min lang an." }
entries[33908] = { ["name"] = "Brennende Stacheln", ["text"] = "30 Meter Reichweite\nAus dem befreundeten Ziel sprießen Dornen, die jedem Angreifer 5 Feuerschaden zufügen. Hält until cancelled lang an." }
entries[33909] = { ["name"] = "Überragen", ["text"] = "Sofort\nErhöht den vom Zaubernden verursachten körperlichen Schaden until cancelled lang um 10%." }
entries[33910] = { ["name"] = "Andere Heilen", ["text"] = "215 Mana 40 Meter Reichweite\nWirken in 4 sek.\nRuft heilige Magie herbei, um einen Verbündeten zu heilen." }
entries[33911] = { ["name"] = "Rüstung zerfetzen", ["text"] = "Nahkampfreichweite\nSofort\nHackt auf die Rüstung eines Gegners ein und verringert sie pro Einsatz von 'Rüstung zerreißen'. Kann bis zu 5-mal angewendet werden. Hält 30 sec lang an." }
entries[33912] = { ["name"] = "Zerfetzen", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 15 sec lang alle 3 Sek. körperlichen Schaden zu." }
entries[33913] = { ["name"] = "Seelenbrand", ["text"] = "40 Meter Reichweite\nSofort\nFügt einem Gegner 6 sec lang insgesamt 1500 Feuerschaden zu, hindert ihn daran, Zauber zu wirken, und verringert den von ihm zugefügten körperlichen Schaden um 50%." }
entries[33914] = { ["name"] = "Schattenschlag", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nSchlägt einen Gegner und verursacht Waffenschaden sowie zusätzlichen Bonusschaden." }
entries[33915] = { ["name"] = "Entzug der Leere" }
entries[33916] = { ["name"] = "Entzug der Leere", ["text"] = "25 Mana\nWirken in 3 sek.\nEntzieht allen Gegnern in einem Radius von 10 Metern Gesundheit." }
entries[33917] = { ["name"] = "Zerfleischen", ["text"] = "100 Meter Reichweite\nSofort\nZerfleischt das Ziel, verursacht Schaden und lässt es 1 min lang zusätzlichen Schaden durch Blutungseffekte erleiden. Diese Fähigkeit kann in Katzen- und Terrorbärengestalt angewendet werden." }
entries[33918] = { ["name"] = "Kristallkanal" }
entries[33919] = { ["name"] = "Erdbeben", ["text"] = "Wirken in 1 sek. 6 sek. Abklingzeit\nFügt nahen Gegnern 919 to 1181 körperlichen Schaden zu, betäubt sie 3 sec lang." }
entries[33923] = { ["name"] = "Überschallknall", ["text"] = "Wirken in 5 sek. 7 sek. Abklingzeit\nVerursacht einen massiven Ausbruch von Schallenergie, die Gegnern in der Nähe Naturschaden zufügt und anschließend 9 sec lang alle 3 Sek. zusätzlichen Naturschaden verursacht. Unter dem Einfluss von 'Überschallknall' verringert sich das gegnerische Bewegungstempo um 90%." }
entries[33924] = { ["name"] = "Furcht", ["text"] = "20 Meter Reichweite\nWirken in 1.5 sek.\nErfüllt einen Feind mit Furcht, woraufhin er bis zu 4 sec lang voller Schrecken flüchtet. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden." }
entries[33925] = { ["name"] = "Phantomstoß", ["text"] = "20 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nAngriffs- und Zaubertempo um 50% verlangsamt.\nAlle 3 Sek. Naturschaden verursacht.\nHält 12 sec an." }
entries[33926] = { ["name"] = "Elunes Berührung", ["text"] = "Sofort\nStellt 1 Mana wieder her." }
entries[33928] = { ["name"] = "Eintauchen des Sandwurms" }
entries[33929] = { ["name"] = "Elementartotem", ["text"] = "Sofort\nBeschwört ein Totem das einen Elementar herbeiruft, der 10 min lang Dinge tut." }
entries[33930] = { ["name"] = "Elementartotem" }
entries[33932] = { ["name"] = "Tunnel", ["text"] = "Wirken in 1.5 sek.\nTeleportiert den Zaubernden vorwärts, solange nichts im Weg ist." }
entries[33933] = { ["name"] = "Druckwelle", ["text"] = "7% von Grundmana\nSofort 30 sek. Abklingzeit\nEine Flammenwelle geht vom Zaubernden aus. Alle Feinde, die sich im Radius der Flammen befinden, erleiden 629 to 738 Feuerschaden, werden zurückgestoßen und sind 6 sec lang benommen." }
entries[33937] = { ["name"] = "Einheiten der Phase 2 betäuben" }
entries[33938] = { ["name"] = "Pyroschlag", ["text"] = "22% von Grundmana 35 Meter Reichweite\nWirken in 5 sek.\nSchleudert einen immensen feurigen Felsen, der 971 to 1224 Feuerschaden sowie zusätzlich 12 sec lang insgesamt 356 Feuerschaden verursacht." }
entries[33943] = { ["name"] = "Fluggestalt", ["text"] = "13% von Grundmana\nSofort\nVerwandelt Euch in eine Fluggestalt, erhöht Euer Bewegungstempo um 150% und ermöglicht es Euch, zu fliegen. Kann nur in der Scherbenwelt, in Nordend und nicht im Kampf angewendet werden.\n\nDer Akt des Gestaltwandelns befreit den Zaubernden von Verwandlungs- und bewegungseinschränkenden Effekten." }
entries[33944] = { ["name"] = "Magie dämpfen", ["text"] = "27% von Grundmana 30 Meter Reichweite\nSofort\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 120 und Heilzauber um bis zu 128 verringert werden. Hält 10 min lang an." }
entries[33946] = { ["name"] = "Magie verstärken", ["text"] = "27% von Grundmana 30 Meter Reichweite\nSofort\nVerstärkt gegen das anvisierte Gruppenmitglied gerichtete Magie, wobei der von Zaubern zugefügte Schaden um bis zu 120 und Heilzauber um bis zu 128 erhöht werden. Hält 10 min lang an." }
