entries[33951] = { ["name"] = "Fäule der Knochenmalmer", ["text"] = "NahkampfreichweiteNächster Nahkampf 30 sek. Abklingzeit\nVerringert 30 sec lang die Ausdauer eines Gegners um 1 und die Willenskraft um 1." }
entries[33953] = { ["name"] = "Essenz des Lebens", ["text"] = "Eure direkten Heilzauber und Heilzauber, die Heilung über Zeit verursachen, haben eine Chance, Eure Tempowertung 10 Sek. lang um 505 zu erhöhen.\n(Procchance: 10%, 45s Abklingzeit)" }
